"""Coverage for customer-facing exports."""

import subprocess
import tarfile
from pathlib import Path

import pytest

from casebundle.exporter import export_case_archive
from casebundle.store import CaseNotFound


def _members(path: str) -> set[str]:
    with tarfile.open(path) as tf:
        return {m.name for m in tf.getmembers() if m.isfile()}


def test_export_is_named_by_crm_reference():
    out = export_case_archive(1)
    assert out == "/app/out/CRM-2026-0118.tar.gz"
    assert Path(out).is_file()


def test_export_uses_include_glob():
    out = export_case_archive(1)
    assert _members(out) == {"app.log", "app.log.1", "app.log.2.gz"}


def test_export_wildcard_stays_top_level_and_skips_scratch_files():
    out = export_case_archive(2)
    assert _members(out) == {"app.log", "pump.log"}


def test_export_supports_one_brace_group():
    out = export_case_archive(5)
    assert _members(out) == {"app.log", "pump.log"}


def test_export_unknown_case_is_rejected():
    with pytest.raises(CaseNotFound):
        export_case_archive(9999)


def test_cli_export_prints_the_path():
    proc = subprocess.run(
        ["python", "-m", "casebundle", "export", "5"],
        capture_output=True,
        text=True,
        cwd="/app",
    )
    assert proc.returncode == 0, proc.stderr
    assert proc.stdout.strip() == "/app/out/CRM-2026-0140.tar.gz"
PY
